sections.css:
.typography-body-sm {
  font-family: var(--typography-body-sm-font-family);
  font-size: var(--typography-body-sm-font-size);
  font-weight: var(--typography-body-sm-font-weight);
  line-height: var(--typography-body-sm-line-height);
  letter-spacing: var(--typography-body-sm-letter-spacing);
}
.typography-body-sm {
  font-family: var(--typography-body-sm-font-family);
  font-size: var(--typography-body-sm-font-size);
  font-weight: var(--typography-body-sm-font-weight);
  line-height: var(--typography-body-sm-line-height);
  letter-spacing: var(--typography-body-sm-letter-spacing);
}
.cbf-review-notice .esa-alert-box {
  --color-background-utility-info-subtle: var(--color-background-brand-subtle);
  --color-border-utility-info: var(--color-border-brand);
  --color-background-utility-info: var(--color-background-brand-muted);
  --color-content-default-secondary: var(--color-content-default);
  font-size: 15px;
}
.cbf-pdf-panel {
  flex: 1;
  min-width: 0;
  border-right: 1px solid var(--color-border-default);
  display: flex;
  flex-direction: column;
  position: relative;
}
.cbf-pdf-panel[hidden] {
  display: none;
}
.cbf-pdf-panel {
  background: var(--color-background-elevation-sunken, #f8f9fb);
}
.cbf-pdf-drop {
  flex: 1;
  display: flex;
  flex-direction: column;
  align-items: center;
  justify-content: center;
  gap: var(--spacing-300);
  text-align: center;
  margin: var(--spacing-500);
  padding: var(--spacing-700) var(--spacing-600);
  border: 2px dashed var(--color-border-default);
  border-radius: var(--radius-100);
  background: var(--color-background-elevation-raised);
  transition:
    border-color 0.15s ease,
    background 0.15s ease;
}
.cbf-pdf-drop[hidden] {
  display: none;
}
.cbf-pdf-panel.is-over .cbf-pdf-drop {
  border-color: var(--color-background-brand);
  background: var(--color-background-brand-subtle);
}
.cbf-pdf-drop__input {
  position: absolute;
  width: 1px;
  height: 1px;
  opacity: 0;
  pointer-events: none;
}
.cbf-pdf-drop__icon {
  color: var(--color-content-default-tertiary);
}
.cbf-pdf-drop__heading {
  margin: 0;
  font-size: 16px;
  font-weight: var(--typography-font-weight-semibold);
  color: var(--color-content-default);
}
.cbf-pdf-drop__sub {
  margin: 0;
  font-size: 14px;
  color: var(--color-content-default-secondary);
}
.cbf-pdf-drop__browse {
  color: var(--color-background-brand-muted);
  font-weight: var(--typography-font-weight-semibold);
  text-decoration: underline;
  text-underline-offset: 2px;
}
.cbf-pdf-drop__browse:hover {
  color: var(--color-background-brand);
}
.cbf-pdf-drop__hint {
  margin: 0;
  font-size: 12px;
  color: var(--color-content-default-tertiary);
}
.cbf-pdf-drop__error {
  width: 100%;
  max-width: 360px;
  margin-top: var(--spacing-200);
  margin-inline: auto;
  text-align: left;
}
.cbf-pdf-drop__error[hidden] {
  display: none;
}
.cbf-pdf-viewer {
  flex: 1;
  display: flex;
  flex-direction: column;
  min-height: 0;
}
.cbf-pdf-viewer[hidden] {
  display: none;
}
.cbf-pdf-viewer__bar {
  display: flex;
  align-items: center;
  gap: var(--spacing-200);
  padding: 0 var(--spacing-400);
  height: 40px;
  flex: none;
  border-bottom: 1px solid var(--color-border-default);
  background: var(--color-background-elevation-raised);
}
.cbf-pdf-viewer__name {
  flex: 1;
  min-width: 0;
  font-size: 13px;
  color: var(--color-content-default-secondary);
  overflow: hidden;
  text-overflow: ellipsis;
  white-space: nowrap;
}
.cbf-pdf-viewer__remove {
  flex: none;
  display: inline-flex;
  align-items: center;
  gap: var(--spacing-150);
  font-size: 12px;
  font-weight: var(--typography-font-weight-semibold);
  color: var(--color-content-default-tertiary);
  padding: var(--spacing-100) var(--spacing-250);
  border: 1px solid var(--color-border-default);
  border-radius: var(--radius-100);
  background: var(--color-background-elevation-raised);
  transition:
    color 0.12s ease,
    border-color 0.12s ease,
    background 0.12s ease;
}
.cbf-pdf-viewer__remove:hover {
  color: var(--color-background-utility-danger, #dc2626);
  border-color: var(--color-background-utility-danger, #dc2626);
  background: var(--color-background-utility-danger-subtle, #fef2f2);
}
.cbf-pdf-viewer__remove[hidden] {
  display: none;
}
.cbf-pdf-viewer__frame {
  flex: 1;
  width: 100%;
  border: none;
  display: block;
  min-height: 0;
}
@media (max-width: 1100px) {
  .cbf-pdf-panel {
    flex: none;
    height: 420px;
    border-right: none;
    border-bottom: 1px solid var(--color-border-default);
  }
}
@media (max-width: 600px) {
  .cbf-pdf-panel:has([data-upload-idle]:not([hidden])) {
    display: none;
  }
}
.esa-alert-box {
  --_alert-bg: var(--color-background-utility-info-subtle, #fbfdff);
  --_alert-border: var(--color-border-utility-info, #acd8fc);
  --_alert-accent: var(--color-content-utility-info, #0d74ce);
  --_alert-icon-color: var(--_alert-accent);
  --_alert-title-color: var(--_alert-accent);
  --_alert-text-color: var(--alert-box-text-color, var(--color-content-default-secondary, #646464));
  display: flex;
  align-items: flex-start;
  gap: var(--spacing-300, 0.75rem);
  padding: var(--spacing-300, 0.75rem) var(--spacing-400, 1rem);
  border: var(--border-width-default, 1px) solid var(--_alert-border);
  border-radius: var(--radius-md, 0.5rem);
  background: var(--_alert-bg);
}
.esa-alert-box--danger {
  --_alert-bg: var(--color-background-utility-danger-subtle, #fffcfc);
  --_alert-border: var(--color-border-utility-danger, #fdbdbe);
  --_alert-accent: var(--color-content-utility-danger, #ce2c31);
}
.esa-alert-box__icon {
  flex-shrink: 0;
  color: var(--_alert-icon-color);
  padding-top: 1px;
}
.esa-alert-box__body {
  flex: 1;
  min-width: 0;
}
.esa-alert-box__message {
  color: var(--_alert-text-color);
}

.typography-body-sm {
  font-family: var(--typography-body-sm-font-family);
  font-size: var(--typography-body-sm-font-size);
  font-weight: var(--typography-body-sm-font-weight);
  line-height: var(--typography-body-sm-line-height);
  letter-spacing: var(--typography-body-sm-letter-spacing);
}
.typography-microcopy-md {
  font-family: var(--typography-microcopy-md-font-family);
  font-size: var(--typography-microcopy-md-font-size);
  font-weight: var(--typography-microcopy-md-font-weight);
  line-height: var(--typography-microcopy-md-line-height);
  letter-spacing: var(--typography-microcopy-md-letter-spacing);
}
.typography-body-sm {
  font-family: var(--typography-body-sm-font-family);
  font-size: var(--typography-body-sm-font-size);
  font-weight: var(--typography-body-sm-font-weight);
  line-height: var(--typography-body-sm-line-height);
  letter-spacing: var(--typography-body-sm-letter-spacing);
}
.typography-microcopy-md {
  font-family: var(--typography-microcopy-md-font-family);
  font-size: var(--typography-microcopy-md-font-size);
  font-weight: var(--typography-microcopy-md-font-weight);
  line-height: var(--typography-microcopy-md-line-height);
  letter-spacing: var(--typography-microcopy-md-letter-spacing);
}
.esa-nav-dropdown .esa-button__native > .esa-icon:last-child {
  transition: transform 0.15s ease;
}
.esa-nav-dropdown[open] .esa-button__native > .esa-icon:last-child {
  transform: rotate(180deg);
}
.esa-button {
  --_btn-pad-y: var(--spacing-300, 0.75rem);
  --_btn-padding-x: var(--spacing-300, 0.75rem);
  --_btn-radius: var(--button-radius-md, 0.5rem);
  --_accent: var(--color-background-brand, #46a758);
  --_accent-hover: var(--color-background-brand-hover, #3e9b4f);
  --_on: var(--color-content-default-knockout, #fcfcfc);
  --_accent-text: var(--_accent);
  --_btn-tint-hover: color-mix(in srgb, var(--_accent) 8%, transparent);
  --_btn-tint-active: color-mix(in srgb, var(--_accent) 14%, transparent);
  display: inline-block;
}
.esa-button--variant-primary {
  --_accent-text: var(--color-content-brand);
}
.esa-button--variant-secondary {
  --_accent: var(--color-background-brand-muted);
  --_accent-hover: var(--color-background-brand-muted-hover);
  --_on: var(--color-content-on-brand-muted, var(--color-content-default));
  --_accent-text: var(--color-content-brand);
  --_accent-border: var(--color-border-default-strong, #bbbbbb);
}
.esa-button--variant-danger {
  --_accent: var(--color-background-utility-danger);
  --_accent-hover: var(--color-background-utility-danger-hover);
  --_accent-text: var(--color-content-utility-danger);
}
.esa-button--appearance-fill .esa-button__native {
  background: var(--_accent);
  color: var(--_on);
  border-color: var(--_accent-border, transparent);
}
.esa-button--appearance-fill .esa-button__native:hover:not(:disabled) {
  background: var(--_accent-hover);
}
.esa-button--appearance-fill.esa-button--active .esa-button__native {
  background: var(--_accent-hover);
}
.esa-button--appearance-outline .esa-button__native,
.esa-button--appearance-dashed .esa-button__native {
  background: transparent;
  color: var(--_accent-text);
  border-color: var(--_accent);
}
.esa-button--appearance-dashed .esa-button__native {
  border-style: dashed;
}
.esa-button--appearance-outline .esa-button__native:hover:not(:disabled),
.esa-button--appearance-dashed .esa-button__native:hover:not(:disabled) {
  background: var(--_btn-tint-hover);
}
.esa-button--appearance-outline.esa-button--active .esa-button__native,
.esa-button--appearance-dashed.esa-button--active .esa-button__native {
  background: var(--_btn-tint-active);
}
.esa-button--appearance-soft .esa-button__native {
  background: color-mix(
    in srgb,
    var(--color-background-elevation-sunken, #f0f0f0) 45%,
    var(--color-background-elevation-raised, #fcfcfc)
  );
  color: var(--_accent-text);
  border-color: var(--color-border-default-strong, #bbbbbb);
}
.esa-button--appearance-soft .esa-button__native:hover:not(:disabled),
.esa-button--appearance-soft.esa-button--active .esa-button__native {
  background: var(--_accent);
  color: var(--_on);
  border-color: var(--_accent);
}
.esa-button--variant-ghost .esa-button__native {
  background: transparent;
  color: var(--color-content-default, #202020);
  border-color: transparent;
}
.esa-button--variant-ghost.esa-button--appearance-outline .esa-button__native,
.esa-button--variant-ghost.esa-button--appearance-dashed .esa-button__native {
  border-color: var(--color-border-default, #cecece);
}
.esa-button--variant-ghost .esa-button__native:hover:not(:disabled),
.esa-button--variant-ghost.esa-button--active .esa-button__native {
  background: var(--color-background-elevation-sunken, #f0f0f0);
}
.esa-button--variant-chrome .esa-button__native {
  background: transparent;
  color: inherit;
  border-color: transparent;
}
.esa-button--variant-chrome .esa-button__native:hover:not(:disabled),
.esa-button--variant-chrome.esa-button--active .esa-button__native,
.esa-button--variant-chrome.esa-button--current .esa-button__native {
  background: var(--button-chrome-bg-hover, color-mix(in srgb, currentColor 14%, transparent));
}
.esa-button--variant-chrome .esa-button__native:focus-visible {
  outline-color: currentColor;
}
.esa-button__native {
  display: inline-flex;
  align-items: center;
  justify-content: center;
  gap: var(--spacing-200, 8px);
  width: 100%;
  padding-block: var(--_btn-pad-y);
  padding-inline: var(--_btn-padding-x);
  border: var(--border-width-default, 1px) solid transparent;
  border-radius: var(--_btn-radius);
  text-decoration: none;
  cursor: pointer;
  transition:
    background var(--transition-fast, 0.15s ease),
    border-color var(--transition-fast, 0.15s ease);
  -webkit-appearance: none;
  appearance: none;
}
.esa-button__native:focus-visible {
  outline: var(--focus-ring-width, 2px) solid var(--focus-ring-color, #3e9b4f);
  outline-offset: var(--focus-ring-offset, 2px);
}
.esa-button--icon-only .esa-button__native {
  padding-inline: var(--_btn-pad-y);
  aspect-ratio: 1;
}
summary.esa-button {
  list-style: none;
  cursor: pointer;
}
summary.esa-button::-webkit-details-marker {
  display: none;
}
summary.esa-button:focus-visible {
  outline: var(--focus-ring-width, 2px) solid var(--focus-ring-color, #3e9b4f);
  outline-offset: var(--focus-ring-offset, 2px);
  border-radius: var(--_btn-radius);
}
.esa-button__label {
  white-space: nowrap;
}
.cbf-line-item {
  display: grid;
  grid-template-columns: minmax(0, 1fr) 56px 96px 88px 32px;
  gap: var(--spacing-200);
  padding: var(--spacing-250) var(--spacing-400);
  border-bottom: 1px solid var(--color-border-default);
  align-items: center;
}
.cbf-line-item:last-child {
  border-bottom: 0;
}
.cbf-li-input {
  box-sizing: border-box;
  width: 100%;
  padding: var(--spacing-150) var(--spacing-250);
  border: 1px solid var(--color-border-default);
  border-radius: var(--radius-100);
  font-family: var(--typography-font-family-sans);
  font-size: 14px;
  color: var(--color-content-default);
  background: var(--color-background-elevation-raised);
  transition:
    border-color 0.12s ease,
    box-shadow 0.12s ease;
  outline: none;
}
.cbf-li-input:focus {
  border-color: var(--color-background-brand);
  box-shadow: 0 0 0 3px var(--color-background-brand-subtle);
}
.cbf-li-input::placeholder {
  color: var(--color-content-default-tertiary);
}
.cbf-li-input:disabled {
  opacity: 0.5;
  cursor: not-allowed;
  background: var(--color-background-elevation-sunken, #f8f9fb);
}
.cbf-li-qty,
.cbf-li-price {
  text-align: right;
}
.cbf-li-total {
  font-size: 14px;
  font-weight: var(--typography-font-weight-semibold);
  color: var(--color-content-default);
  text-align: right;
}
.cbf-li-remove {
  display: flex;
  align-items: center;
  justify-content: center;
  width: 28px;
  height: 28px;
  border-radius: var(--radius-100);
  color: var(--color-content-default-tertiary);
  transition:
    background 0.12s ease,
    color 0.12s ease;
}
.cbf-li-remove:hover {
  background: var(--color-background-elevation-sunken, #f8f9fb);
  color: var(--color-content-default);
}
.cbf-page-title {
  margin: 0 0 var(--spacing-400);
  font-family: var(--typography-font-family-display);
  font-weight: var(--typography-font-weight-medium);
  font-size: 40px;
  line-height: 1;
  letter-spacing: -1px;
  color: var(--color-background-default-knockout);
}
.cbf-form-fields {
  display: flex;
  flex-direction: column;
  gap: var(--spacing-500);
}
.cbf-form-lock {
  display: flex;
  align-items: center;
  gap: var(--spacing-250);
  margin-bottom: var(--spacing-500);
  padding: var(--spacing-300) var(--spacing-400);
  border: 1px solid var(--color-border-default);
  border-radius: var(--radius-100);
  background: var(--color-background-elevation-sunken, #f8f9fb);
  font-size: 13px;
  color: var(--color-content-default-tertiary);
  line-height: 1.4;
}
.cbf-form-lock svg {
  flex: none;
  color: var(--color-content-default-tertiary);
}
.cbf-form-lock[hidden],
.cbf-form-lock__msg--narrow,
.cbf-form-lock__upload-btn {
  display: none;
}
@media (max-width: 1100px) {
  .cbf-form-lock__msg--wide {
    display: none;
  }
}
@media (max-width: 1100px) {
  .cbf-form-lock__msg--narrow {
    display: inline;
  }
}
@media (max-width: 1100px) {
  .cbf-form-lock__upload-btn {
    display: inline-flex;
    align-items: center;
    gap: var(--spacing-150);
    margin-left: auto;
    flex: none;
    padding: var(--spacing-150) var(--spacing-300);
    border: 1px solid var(--color-border-default);
    border-radius: var(--radius-100);
    font-size: 13px;
    font-weight: var(--typography-font-weight-semibold);
    color: var(--color-background-brand-muted);
    background: var(--color-background-elevation-raised);
    transition:
      background 0.12s ease,
      border-color 0.12s ease;
  }
}
@media (max-width: 1100px) {
  .cbf-form-lock__upload-btn:hover {
    background: var(--color-background-brand-subtle);
    border-color: var(--color-border-brand);
  }
}
@media (max-width: 600px) {
  .cbf-form-lock {
    flex-wrap: wrap;
  }
}
@media (max-width: 600px) {
  .cbf-form-lock__upload-btn {
    width: 100%;
    margin-left: 0;
    justify-content: center;
    gap: var(--spacing-200);
    padding: var(--spacing-300) var(--spacing-400);
    font-size: 16px;
    color: var(--color-content-default-knockout, #fff);
    background: var(--color-background-brand);
    border-color: var(--color-background-brand);
  }
}
@media (max-width: 600px) {
  .cbf-form-lock__upload-btn svg {
    width: 17px;
    height: 17px;
  }
}
@media (max-width: 600px) {
  .cbf-form-lock__upload-btn:hover {
    background: var(--color-background-brand-hover, var(--color-background-brand-muted));
    border-color: var(--color-background-brand-hover, var(--color-background-brand-muted));
  }
}
.cbf-mobile-pdf-input {
  position: absolute;
  width: 1px;
  height: 1px;
  opacity: 0;
  pointer-events: none;
}
.cbf-optional {
  font-size: 13px;
  font-weight: var(--typography-font-weight-regular);
  color: var(--color-content-default-tertiary);
}
.cbf-support-docs-group__label {
  margin: 0 0 var(--spacing-050);
  font-size: var(--font-size-200, 13px);
  font-weight: var(--typography-font-weight-medium);
  color: var(--color-content-default-secondary);
}
.cbf-support-docs-group__desc {
  margin: 0 0 var(--spacing-300);
  font-size: 13px;
  color: var(--color-content-default-tertiary);
  line-height: 1.5;
}
.cbf-line-items {
  border: 1px solid var(--color-border-default);
  border-radius: var(--radius-100);
  overflow: hidden;
}
.cbf-line-items__head {
  display: grid;
  grid-template-columns: minmax(0, 1fr) 56px 96px 88px 32px;
  gap: var(--spacing-200);
  padding: var(--spacing-300) var(--spacing-400);
  background: var(--color-background-elevation-sunken, #f8f9fb);
  border-bottom: 1px solid var(--color-border-default);
  font-size: 12px;
  font-weight: var(--typography-font-weight-semibold);
  text-transform: uppercase;
  letter-spacing: 0.04em;
  color: var(--color-content-default-tertiary);
}
.cbf-line-items__body {
  display: flex;
  flex-direction: column;
}
.cbf-line-items__foot {
  display: flex;
  align-items: center;
  justify-content: space-between;
  padding: var(--spacing-300) var(--spacing-400);
  border-top: 1px solid var(--color-border-default);
  background: var(--color-background-elevation-sunken, #f8f9fb);
}
.cbf-add-row {
  display: inline-flex;
  align-items: center;
  gap: var(--spacing-150);
  font-size: 14px;
  font-weight: var(--typography-font-weight-semibold);
  color: var(--color-background-brand-muted);
  padding: var(--spacing-150) var(--spacing-200);
  border-radius: var(--radius-100);
  transition: background 0.12s ease;
}
.cbf-add-row:hover {
  background: var(--color-background-brand-subtle);
}
.cbf-add-row:disabled {
  opacity: 0.4;
  cursor: not-allowed;
}
.cbf-line-items__total {
  display: flex;
  align-items: center;
  gap: var(--spacing-300);
  font-size: 15px;
  color: var(--color-content-default-secondary);
}
.cbf-line-items__total strong {
  font-size: 17px;
  font-weight: var(--typography-font-weight-semibold);
  color: var(--color-content-default);
}
.cbf-final-invoice {
  padding: var(--spacing-400) var(--spacing-450, var(--spacing-400));
  border: 1px solid var(--color-border-default);
  border-radius: var(--radius-100);
  background: var(--color-background-elevation-sunken, #f8f9fb);
  transition:
    border-color 0.15s ease,
    background 0.15s ease,
    box-shadow 0.15s ease;
}
.cbf-final-invoice.is-flagged {
  border-color: var(--color-border-brand, var(--color-background-brand));
  background: var(--color-background-brand-subtle);
  box-shadow: 0 0 0 1px var(--color-border-brand, var(--color-background-brand));
}
.cbf-support-docs {
  border: 1px solid var(--color-border-default);
  border-radius: var(--radius-100);
  overflow: hidden;
  transition:
    border-color 0.12s ease,
    background 0.12s ease;
}
.cbf-support-docs.is-over {
  border-color: var(--color-background-brand);
